import {analyze,rankedLines} from './match.js';
import {readResumeFile} from './resume-import.js';
import {highlightsHTML} from './jd-view.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const statuses=['Saved','Applied','Received call back','Interview','Offer','Rejected','Withdrawn'];
const key='hirizz.workspace.v1';let state={resume:'',resumeName:'',jobs:[]};let view='applications',tab='All opportunities',query='',filter='All statuses',editing=null,detailId=null;
try{const saved=JSON.parse(localStorage.getItem(key));if(valid(saved))state=saved;}catch{toast('Could not load saved workspace. Import a backup if needed.');}
function valid(s){return s&&typeof s.resume==='string'&&typeof s.resumeName==='string'&&Array.isArray(s.jobs)&&s.jobs.every(j=>j&&typeof j.id==='string'&&['company','role','jd','status','notes','url','location','followup','created'].every(k=>typeof j[k]==='string')&&statuses.includes(j.status)&&Array.isArray(j.history)&&j.history.every(h=>h&&typeof h.at==='string'&&typeof h.status==='string')&&(!j.draft||typeof j.draft==='string'));}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{toast('Storage is full or unavailable. Export a backup to keep your changes.');return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>t?new Date(t.includes('T')?t:t+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const cls=s=>({'Received call back':'callback','Rejected':'rejected','Interview':'interview','Applied':'applied','Offer':'offer'}[s]||'saved');
const options=s=>statuses.map(v=>`<option ${v===s?'selected':''}>${esc(v)}</option>`).join('');
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent=view==='resume'?'Base resume':view==='insights'?'Insights':'Applications';if(view==='resume')renderResume();else if(view==='insights')renderInsights();else renderApplications();}
function renderApplications(){const jobs=state.jobs;const applied=jobs.filter(j=>j.history.some(h=>h.status==='Applied')||j.status==='Applied').length;const conversations=jobs.filter(j=>['Received call back','Interview'].includes(j.status)).length;$('#content').innerHTML=heading('YOUR NEXT CHAPTER STARTS HERE','Make room for what’s next.','A clear view of your job search. One opportunity at a time.','<button class="primary" id="add-job">＋ Add opportunity</button>')+`<div class="stats">${[['Total opportunities',jobs.length,'Your possibilities, in one place','▦'],['Applications sent',applied,'Every application is a step forward','↗'],['In conversation',conversations,'Call backs & interviews','☏'],['Offers received',jobs.filter(j=>j.status==='Offer').length,'The next chapter is getting closer','✧']].map(([a,b,c,d])=>`<div class="stat"><div class="stat-top">${a}<span class="stat-icon">${d}</span></div><strong>${b.toString().padStart(2,'0')}</strong><small>${c}</small></div>`).join('')}</div><div class="banner"><div class="banner-icon">▤</div><div><strong>${state.resume?'Your base resume is ready. Make every application count.':'Start with your story. Add your base resume.'}</strong><p>${state.resume?'Compare a job description with your real experience before you apply.':'One source of truth for every match check and tailored draft.'}</p></div><button class="secondary" id="go-resume">${state.resume?'Manage resume':'Add base resume'} ↗</button></div><div class="table-top"><div class="section-title"><h2 class="section-label">Your opportunities</h2><span class="count">${jobs.length}</span></div><div class="tools"><input class="search" id="search" aria-label="Search opportunities" placeholder="⌕  Search company or role…" value="${esc(query)}"><select id="status-filter" aria-label="Filter status"><option>All statuses</option>${options(filter)}</select></div></div><div class="tabs">${['All opportunities','Saved','Applied','In conversation','Closed'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="table-wrap" id="table"></div><p class="mini-note">Match scores are transparent keyword estimates, not scores from an employer’s ATS.</p><div class="bottom-card"><span>✳</span><div><strong>Your experience is enough to tell a great story.</strong><p>Hirizz helps surface relevant experience. It never invents skills, achievements, or qualifications.</p></div></div>`;$('#add-job').onclick=()=>openJob();$('#go-resume').onclick=()=>{view='resume';render();};$('#search').oninput=e=>{query=e.target.value;renderTable();};$('#status-filter').value=filter;$('#status-filter').onchange=e=>{filter=e.target.value;renderTable();};$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderApplications();});renderTable();}
function renderTable(){const jobs=state.jobs.filter(j=>(j.company+' '+j.role).toLowerCase().includes(query.toLowerCase())&&(filter==='All statuses'||j.status===filter)&&(tab==='All opportunities'||tab===j.status||(tab==='In conversation'&&['Received call back','Interview'].includes(j.status))||(tab==='Closed'&&['Rejected','Withdrawn','Offer'].includes(j.status))));$('#table').innerHTML=jobs.length?`<table><thead><tr><th>Company</th><th>Role / location</th><th>Status</th><th>Keyword match</th><th>Added</th><th>Follow up</th><th></th></tr></thead><tbody>${jobs.map(j=>{const a=state.resume&&j.jd?analyze(state.resume,j.jd):null;return `<tr><td><div class="company-cell"><div class="company-logo">${esc(j.company[0].toUpperCase())}</div><div><strong>${esc(j.company)}</strong><small>Opportunity</small></div></div></td><td><button class="role-link" data-open="${esc(j.id)}">${esc(j.role)}</button><div class="help">${esc(j.location||'Location not added')}</div></td><td><select class="status ${cls(j.status)}" aria-label="Status for ${esc(j.role)} at ${esc(j.company)}" data-status="${esc(j.id)}">${options(j.status)}</select></td><td>${a?`<div class="score"><span>${a.score}%</span><div class="score-track"><div class="score-fill" style="width:${a.score}%"></div></div></div>`:'<span class="help">Not scanned</span>'}</td><td>${date(j.created)}</td><td>${date(j.followup)}</td><td><button class="quiet" data-open="${esc(j.id)}" aria-label="Open opportunity">↗</button></td></tr>`;}).join('')}</tbody></table>`:`<div class="empty"><span style="font-size:30px">↗</span><h3>${state.jobs.length?'No opportunities match your filters.':'Your next chapter is a blank canvas.'}</h3><p>${state.jobs.length?'Try another search or status.':'Save a role you’re excited about, check the fit,<br>and keep every next step in one place.'}</p>${state.jobs.length?'':'<button class="primary" id="first-job">＋ Add your first opportunity</button>'}</div>`;if($('#first-job'))$('#first-job').onclick=()=>openJob();$$('[data-open]').forEach(b=>b.onclick=()=>showDetail(b.dataset.open));$$('[data-status]').forEach(s=>s.onchange=()=>{setStatus(s.dataset.status,s.value);render();});}
function setStatus(id,status){const j=state.jobs.find(j=>j.id===id);if(j.status!==status){j.status=status;j.history.push({status,at:new Date().toISOString()});save();toast('Application status updated');}}
let importedJob=null,importController=null,importSequence=0,importTimer=null;
function resetImport(){clearTimeout(importTimer);importController?.abort();importSequence++;importController=null;importedJob=null;$('#parse-jd').disabled=false;$('#parse-jd').textContent='Read job link ↗';$('#jd-preview').innerHTML='';$('#jd-import-status').textContent='Paste the job posting link. Hirizz will retrieve the description and key details automatically.';}
function openJob(id){editing=id||null;resetImport();const form=$('#job-form');form.reset();form.elements.status.innerHTML=options('Saved');if(id){const j=state.jobs.find(j=>j.id===id);for(const k of ['company','role','location','url','jd','status','followup','notes'])form.elements[k].value=j[k];if(j.parsedJob){importedJob={...j.parsedJob,inputUrl:j.url};$('#jd-preview').innerHTML=highlightsHTML(importedJob);$('#jd-import-status').textContent='Previously imported job details. Read the link again to refresh.';}}$('#job-dialog').showModal();}
async function readJobLink(){
  clearTimeout(importTimer);const form=$('#job-form'),inputUrl=form.elements.url.value.trim();
  if(!inputUrl){$('#jd-import-status').textContent='Enter a job posting link first.';return false;}
  try{const u=new URL(inputUrl);if(u.protocol!=='https:')throw Error();}catch{$('#jd-import-status').textContent='Enter a valid HTTPS job posting link.';return false;}
  importController?.abort();const controller=new AbortController();importController=controller;const seq=++importSequence;const priorJD=form.elements.jd.value;importedJob=null;
  $('#parse-jd').disabled=true;$('#parse-jd').textContent='Reading…';$('#jd-preview').innerHTML='';$('#jd-import-status').textContent='Reading the job posting and extracting details…';
  try{const response=await fetch('/api/job-description',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:inputUrl}),signal:controller.signal});let result;try{result=await response.json();}catch{throw Error('The job importer is unavailable. Please refresh and try again.');}if(!response.ok)throw Error(result.error||'Could not read this job link.');if(seq!==importSequence||form.elements.url.value.trim()!==inputUrl)return false;
    importedJob={...result,inputUrl};form.elements.jd.value=result.description;for(const k of ['company','role','location'])if(result[k]&&!form.elements[k].value.trim())form.elements[k].value=result[k].slice(0,k==='company'?150:k==='role'?200:500);
    $('#jd-preview').innerHTML=highlightsHTML(importedJob);$('#jd-import-status').textContent='Job description imported. Review the extracted details and save your opportunity.';return true;
  }catch(error){if(seq!==importSequence)return false;form.elements.jd.value=priorJD;$('#jd-import-status').textContent=error.name==='AbortError'?'Import cancelled. Try the link again.':error.message;$('#jd-import-status').classList.add('import-error');return false;}
  finally{if(seq===importSequence){$('#parse-jd').disabled=false;$('#parse-jd').textContent='Read job link ↗';importController=null;}}
}
$('#parse-jd').onclick=()=>{$('#jd-import-status').classList.remove('import-error');readJobLink();};
$('#job-form').elements.url.addEventListener('input',()=>{importController?.abort();importSequence++;importedJob=null;$('#job-form').elements.jd.value='';$('#jd-preview').innerHTML='';$('#parse-jd').disabled=false;$('#parse-jd').textContent='Read job link ↗';$('#jd-import-status').classList.remove('import-error');$('#jd-import-status').textContent='Ready to read this job link.';clearTimeout(importTimer);if($('#job-form').elements.url.value.trim())importTimer=setTimeout(()=>readJobLink(),800);});
$('#job-dialog').addEventListener('close',()=>{clearTimeout(importTimer);importController?.abort();importSequence++;});
$('#job-form').onsubmit=async e=>{e.preventDefault();const form=e.target,saveButton=form.querySelector('.modal-actions .primary');saveButton.disabled=true;
  try{const url=form.elements.url.value.trim();const existing=editing?state.jobs.find(j=>j.id===editing):null;
    if(url&&importedJob?.inputUrl!==url&&!(existing?.url===url&&existing.jd&&!importedJob)){if(!await readJobLink())return;}
    const f=Object.fromEntries(new FormData(form));f.url=url;f.company=f.company.trim();f.role=f.role.trim();if(!f.company||!f.role)return toast('Enter a company and role. Some postings do not include these details.');
    if(f.url&&!/^https:\/\//i.test(f.url))return toast('Use an HTTPS job link.');
    if(importedJob)f.parsedJob=importedJob;else if(existing&&existing.url!==url)f.parsedJob=null;
    if(editing){const j=state.jobs.find(j=>j.id===editing);if(j.status!==f.status)j.history.push({status:f.status,at:new Date().toISOString()});Object.assign(j,f);}else state.jobs.unshift({...f,id:crypto.randomUUID(),created:new Date().toISOString(),history:[{status:f.status,at:new Date().toISOString()}],draft:''});
    save();$('#job-dialog').close();render();if(detailId&&$('#detail-dialog').open)showDetail(detailId);toast('Opportunity saved');
  }finally{saveButton.disabled=false;}
};
$$('.close-dialog').forEach(b=>b.onclick=()=>$('#job-dialog').close());
function renderResume(){$('#content').innerHTML=heading('THE FOUNDATION','Your story, in your words.','Keep one base resume as the source of truth for every application.')+`<div class="panel"><div class="table-top"><div><h2 class="section-label">Base resume</h2><p class="help">Paste your resume text, or upload a Word (.docx) or text (.txt) file up to 5 MB. Review the extracted text before saving. Older .doc files must be saved as .docx in Word first.</p></div><button class="secondary" id="upload">Upload resume ↗</button><input type="file" id="resume-file" accept=".docx,.txt,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" hidden></div><label>Resume name<input id="resume-name" value="${esc(state.resumeName)}" placeholder="e.g. My master resume"></label><label for="resume-text">Resume content</label><textarea id="resume-text" class="resume-text" placeholder="Paste your full resume here. Include your summary, skills, experience, and education.">${esc(state.resume)}</textarea><div class="modal-actions"><button class="secondary" id="download-base">Download .txt</button><button class="primary" id="save-resume">Save base resume</button></div><p class="help">Stored only in this browser. Export a workspace backup regularly. Saving a new base updates match estimates; existing tailored drafts stay as saved.</p></div>`;$('#upload').onclick=()=>$('#resume-file').click();$('#resume-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;const target=$('#resume-text'),name=$('#resume-name'),button=$('#upload');button.disabled=true;button.textContent='Reading resume…';try{const text=await readResumeFile(f);if(!target.isConnected)return;target.value=text;name.value=f.name;toast('Resume imported. Review the text, then save your base resume.');}catch(error){toast(error.message);}finally{button.disabled=false;button.textContent='Upload resume ↗';e.target.value='';}};$('#save-resume').onclick=()=>{state.resume=$('#resume-text').value;state.resumeName=$('#resume-name').value;if(save())toast('Base resume saved');};$('#download-base').onclick=()=>download('hirizz-base-resume.txt',$('#resume-text').value);}
function showDetail(id){detailId=id;const j=state.jobs.find(j=>j.id===id);if(!j)return;const a=state.resume&&j.jd?analyze(state.resume,j.jd):null;$('#detail-content').innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${esc(j.company)}</span><h2>${esc(j.role)}</h2><p class="help">${esc(j.location||'Location not added')}</p></div><button class="icon" id="close-detail" aria-label="Close">×</button></div><div class="detail-actions"><select id="detail-status" class="status ${cls(j.status)}" aria-label="Application status">${options(j.status)}</select><button class="secondary" id="edit-job">Edit details</button>${/^https?:\/\//i.test(j.url)?`<a class="secondary" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">View job ↗</a>`:''}<button class="quiet danger" id="delete-job">Delete</button></div>${highlightsHTML(j.parsedJob)}<div class="panel"><span class="eyebrow">RESUME FIT</span>${a?`<div class="score-big">${a.score}% <small>keyword match estimate · ${a.matched.length} of ${a.total} terms</small></div><p class="help">Exact unique-word overlap between the job description and your base resume. This does not assess qualifications or predict an employer’s ATS score.</p><h4>Already in your story</h4><div class="chips">${a.matched.map(t=>`<span class="chip">${esc(t)}</span>`).join('')||'<span class="help">No shared keywords found.</span>'}</div><h4>Gaps to review</h4><div class="chips">${a.missing.map(t=>`<span class="chip missing">${esc(t)}</span>`).join('')||'<span class="help">All extracted terms appear in your resume.</span>'}</div><p class="help">Some terms may be general words. Check whether missing terms represent real requirements. Add them manually only when supported by your actual experience.</p>`:'<h3>Ready when you are.</h3><p class="help">Save a base resume and read the job posting link to see a keyword match.</p>'}</div><div class="panel"><h2 class="section-label">Build an evidence-based draft</h2><p class="help">Select relevant lines from your base resume below. The draft copies selected lines exactly and preserves their original order. Review before sending; no rewriting or new claims are generated.</p>${state.resume?`<details><summary>Choose resume lines (${rankedLines(state.resume,j.jd).length})</summary><p class="help">Lines with more job-description keywords appear first here.</p>${rankedLines(state.resume,j.jd).map(l=>`<label class="evidence"><input type="checkbox" data-line="${l.index}" checked><span>${esc(l.text)}</span></label>`).join('')}</details><div class="modal-actions"><button class="secondary" id="generate-draft">Create draft from selected lines</button></div>`:'<p class="help">Add your base resume first.</p>'}<label>Tailored resume draft<textarea id="draft" rows="9" placeholder="Your selected resume content will appear here.">${esc(j.draft||'')}</textarea></label><div class="detail-actions"><button class="primary" id="save-draft">Save draft</button><button class="secondary" id="download-draft">Download .txt</button><button class="secondary" id="print-draft">Print / Save PDF</button></div><p class="help">Manual edits are yours to verify. Creating a draft replaces the text in this editor; save it to keep it.</p></div><div class="detail-grid"><div><h4>Notes & next steps</h4><p class="help" style="white-space:pre-wrap">${esc(j.notes||'No notes yet. Use Edit details to add some.')}</p><p class="help">Follow up: ${date(j.followup)}</p><details><summary>Job description</summary><p class="help" style="white-space:pre-wrap">${esc(j.jd||'No description imported yet.')}</p></details></div><div><h4>Status history</h4><div class="history">${j.history.slice().reverse().map(h=>`<div>${esc(h.status)} · ${date(h.at)}</div>`).join('')}</div></div></div>`;$('#close-detail').onclick=()=>$('#detail-dialog').close();$('#detail-status').onchange=e=>{setStatus(id,e.target.value);render();showDetail(id);};$('#edit-job').onclick=()=>openJob(id);$('#delete-job').onclick=()=>{if(confirm(`Delete ${j.role} at ${j.company}?`)){state.jobs=state.jobs.filter(x=>x.id!==id);save();$('#detail-dialog').close();detailId=null;render();}};if($('#generate-draft'))$('#generate-draft').onclick=()=>{const selected=new Set($$('[data-line]:checked').map(i=>Number(i.dataset.line)));$('#draft').value=state.resume.split('\n').filter((_,i)=>selected.has(i)).join('\n');toast('Draft created using your exact resume text');};$('#save-draft').onclick=()=>{j.draft=$('#draft').value;if(save())toast('Tailored draft saved');};$('#download-draft').onclick=()=>download('hirizz-tailored-resume.txt',$('#draft').value);$('#print-draft').onclick=()=>{const w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print your resume.');w.document.write(`<html><head><title>Resume</title><style>body{font:12pt/1.5 Arial;margin:2cm;white-space:pre-wrap}</style></head><body>${esc($('#draft').value)}</body></html>`);w.document.close();w.focus();w.print();};if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function renderInsights(){const total=state.jobs.length;const applied=state.jobs.filter(j=>j.history.some(h=>h.status==='Applied')).length;const responded=state.jobs.filter(j=>j.history.some(h=>['Received call back','Interview','Offer'].includes(h.status))).length;$('#content').innerHTML=heading('A LITTLE PERSPECTIVE','See your progress.','Every saved role, conversation, and next step adds up.')+`<div class="panel"><h2 class="section-label">Your application pipeline</h2>${statuses.map(s=>{const n=state.jobs.filter(j=>j.status===s).length;return `<div style="margin:22px 0"><div class="stat-top"><span>${s}</span><strong>${n}</strong></div><div style="height:8px;background:#edf0e6;margin-top:10px;border-radius:5px"><div style="height:100%;background:#86a266;border-radius:5px;width:${total?n/total*100:0}%"></div></div></div>`;}).join('')}<p class="help">${applied} opportunities have an Applied event. ${responded} have a call back, interview, or offer event. Counts reflect your manual status history.</p></div>`;}
$$('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#export').onclick=()=>download(`hirizz-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),'application/json');$('#import').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error();const next=JSON.parse(await f.text());if(!valid(next)||new Set(next.jobs.map(j=>j.id)).size!==next.jobs.length)throw Error();if(!confirm('Replace this browser’s workspace with this backup? Export your current data first if needed.'))return;state=next;save();render();toast('Workspace imported');}catch{toast('Could not import: choose a valid Hirizz backup.');}finally{e.target.value='';}};render();
